create extension if not exists pgcrypto;
create schema if not exists private;
create type public.app_role as enum ('customer', 'admin');
create type public.research_status as enum ('queued','identifying','collecting_evidence','validating_sources','calculating_financials','synthesizing','completed','partial','failed');
create type public.evidence_state as enum ('verified','estimated','user_provided','unverified','unavailable');
create type public.order_status as enum ('pending','paid','failed','refunded','cancelled');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role public.app_role not null default 'customer', locale text not null default 'vi-VN', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name_vi text not null, regulated_hint boolean not null default false, active boolean not null default true);
create table public.plans (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, price_vnd integer not null check (price_vnd >= 0), entitlements jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 2 and 160), target_market text not null default 'VN', sales_channels text[] not null default '{}', category_id uuid references public.categories(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index projects_owner_id_idx on public.projects(owner_id);
create table public.product_inputs (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, product_name text not null, reference_url text, description text, image_path text, expected_price_vnd numeric(14,2), user_assumptions jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index product_inputs_owner_id_idx on public.product_inputs(owner_id); create index product_inputs_project_id_idx on public.product_inputs(project_id);
create table public.product_configurations (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, label text not null, attributes jsonb not null default '{}'::jsonb, selected boolean not null default false, clarification_required boolean not null default false, created_at timestamptz not null default now());
create index product_configurations_owner_id_idx on public.product_configurations(owner_id);
create table public.research_jobs (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, status public.research_status not null default 'queued', input_snapshot jsonb not null, idempotency_key uuid not null unique, attempt_count integer not null default 0 check (attempt_count >= 0), error_code text, error_detail text, credit_redemption_id uuid, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create index research_jobs_owner_id_idx on public.research_jobs(owner_id); create index research_jobs_status_idx on public.research_jobs(status,created_at);
create table public.reports (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, job_id uuid not null references public.research_jobs(id), owner_id uuid not null references auth.users(id) on delete cascade, tier_code text not null references public.plans(code), current_version integer not null default 1, verdict text check (verdict in ('GO','TEST','HOLD','AVOID')), evidence_coverage public.evidence_state not null default 'unavailable', structured_report jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index reports_owner_id_idx on public.reports(owner_id);
create table public.report_versions (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, version integer not null, snapshot jsonb not null, created_at timestamptz not null default now(), unique(report_id,version));
create index report_versions_owner_id_idx on public.report_versions(owner_id);
create table public.sources (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, url text not null, source_type text not null, title text, retrieved_at timestamptz not null, content_hash text, provider text not null, limitations text, created_at timestamptz not null default now(), unique(project_id,url,content_hash));
create index sources_owner_id_idx on public.sources(owner_id);
create table public.evidence_records (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, source_id uuid references public.sources(id) on delete set null, state public.evidence_state not null, observation jsonb not null, observed_at timestamptz, created_at timestamptz not null default now());
create index evidence_records_owner_id_idx on public.evidence_records(owner_id);
create table public.claims (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, report_id uuid not null references public.reports(id) on delete cascade, claim_text text not null, state public.evidence_state not null, confidence numeric(4,3) check (confidence between 0 and 1), created_at timestamptz not null default now());
create index claims_owner_id_idx on public.claims(owner_id);
create table public.claim_evidence (claim_id uuid not null references public.claims(id) on delete cascade, evidence_id uuid not null references public.evidence_records(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, primary key(claim_id,evidence_id));
create index claim_evidence_owner_id_idx on public.claim_evidence(owner_id);
create table public.competitor_listings (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, source_id uuid not null references public.sources(id), title text not null, seller text, platform text, public_price numeric(14,2), currency text, attributes jsonb not null default '{}'::jsonb, similarity text not null check (similarity in ('comparable','partial','not_comparable')), observed_at timestamptz not null, created_at timestamptz not null default now());
create index competitor_listings_owner_id_idx on public.competitor_listings(owner_id);
create table public.suppliers (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, source_id uuid not null references public.sources(id), name text not null, location text, listing_found boolean not null default true, identity_verified boolean not null default false, quality_audited boolean not null default false, limitations text, created_at timestamptz not null default now());
create index suppliers_owner_id_idx on public.suppliers(owner_id);
create table public.supplier_quotations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, supplier_id uuid not null references public.suppliers(id) on delete cascade, price_min numeric(14,2), price_max numeric(14,2), currency text, moq integer check (moq >= 0), incoterm text, evidence_id uuid references public.evidence_records(id), quoted_at timestamptz, created_at timestamptz not null default now());
create index supplier_quotations_owner_id_idx on public.supplier_quotations(owner_id);
create table public.financial_scenarios (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, name text not null, calculation_version text not null, inputs jsonb not null, outputs jsonb not null, created_at timestamptz not null default now());
create index financial_scenarios_owner_id_idx on public.financial_scenarios(owner_id);
create table public.orders (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, plan_id uuid not null references public.plans(id), amount_vnd integer not null check (amount_vnd >= 0), status public.order_status not null default 'pending', provider text, provider_order_id text, idempotency_key uuid not null unique, created_at timestamptz not null default now(), paid_at timestamptz, unique(provider,provider_order_id));
create index orders_owner_id_idx on public.orders(owner_id);
create table public.payments (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, order_id uuid not null references public.orders(id), provider text not null, provider_payment_id text not null, amount_vnd integer not null check (amount_vnd >= 0), verified boolean not null default false, payload_hash text not null, created_at timestamptz not null default now(), unique(provider,provider_payment_id));
create index payments_owner_id_idx on public.payments(owner_id);
create table public.credit_wallets (owner_id uuid primary key references auth.users(id) on delete cascade, balance integer not null default 0 check(balance>=0), updated_at timestamptz not null default now());
create table public.credit_ledger (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, delta integer not null check(delta<>0), reason text not null, order_id uuid references public.orders(id), research_job_id uuid references public.research_jobs(id), idempotency_key text not null unique, created_at timestamptz not null default now());
create index credit_ledger_owner_id_idx on public.credit_ledger(owner_id);
create table public.provider_usage (id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete set null, research_job_id uuid references public.research_jobs(id) on delete set null, provider text not null, operation text not null, units numeric(16,6) not null default 0, cost_usd numeric(16,6) not null default 0, success boolean not null, created_at timestamptz not null default now());
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id) on delete set null, action text not null, target_type text, target_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

insert into public.categories(slug,name_vi,regulated_hint) values ('home-care-organization','Chăm sóc & Sắp xếp nhà cửa',false),('personal-lifestyle','Phong cách sống cá nhân',false),('kitchen-household','Nhà bếp & Gia dụng',true),('pet-accessories','Phụ kiện thú cưng',false),('travel-accessories','Phụ kiện du lịch',false);
insert into public.plans(code,name,price_vnd,entitlements) values ('free','Xem trước miễn phí',0,'{"competitors":0,"suppliers":0,"pdf":false}'),('validate','Validate',49000,'{"competitors":5,"suppliers":3,"pdf":true}'),('research_pro','Research Pro',149000,'{"competitors":15,"suppliers":8,"pdf":true,"advanced_financials":true}'),('launch_ready','Launch Ready',299000,'{"competitors":15,"suppliers":8,"pdf":true,"launch_kit":true}');

do $$ declare t text; begin foreach t in array array['profiles','projects','product_inputs','product_configurations','research_jobs','reports','report_versions','sources','evidence_records','claims','claim_evidence','competitor_listings','suppliers','supplier_quotations','financial_scenarios','orders','payments','credit_wallets','credit_ledger','provider_usage','admin_audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
revoke all on all tables in schema public from anon,authenticated;
grant select on public.categories,public.plans to anon,authenticated;
grant select,insert,update,delete on public.profiles,public.projects,public.product_inputs,public.product_configurations,public.research_jobs,public.reports,public.report_versions,public.sources,public.evidence_records,public.claims,public.claim_evidence,public.competitor_listings,public.suppliers,public.supplier_quotations,public.financial_scenarios,public.orders to authenticated;
grant select on public.payments,public.credit_wallets,public.credit_ledger to authenticated;
create policy "public categories readable" on public.categories for select to anon,authenticated using(active);
create policy "public plans readable" on public.plans for select to anon,authenticated using(active);
create policy "own profile select" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "own profile insert" on public.profiles for insert to authenticated with check((select auth.uid())=id);
create policy "own profile update" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
do $$ declare t text; begin foreach t in array array['projects','product_inputs','product_configurations','research_jobs','reports','report_versions','sources','evidence_records','claims','claim_evidence','competitor_listings','suppliers','supplier_quotations','financial_scenarios','orders'] loop execute format('create policy "own %1$s select" on public.%1$I for select to authenticated using((select auth.uid())=owner_id)',t); execute format('create policy "own %1$s insert" on public.%1$I for insert to authenticated with check((select auth.uid())=owner_id)',t); execute format('create policy "own %1$s update" on public.%1$I for update to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id)',t); execute format('create policy "own %1$s delete" on public.%1$I for delete to authenticated using((select auth.uid())=owner_id)',t); end loop; end $$;
create policy "own payments select" on public.payments for select to authenticated using((select auth.uid())=owner_id);
create policy "own wallet select" on public.credit_wallets for select to authenticated using((select auth.uid())=owner_id);
create policy "own ledger select" on public.credit_ledger for select to authenticated using((select auth.uid())=owner_id);

create or replace function private.apply_credit_entry(p_owner_id uuid,p_delta integer,p_reason text,p_idempotency_key text,p_order_id uuid default null,p_job_id uuid default null) returns integer language plpgsql security definer set search_path='' as $$ declare new_balance integer; begin if p_delta=0 then raise exception 'credit delta cannot be zero'; end if; insert into public.credit_ledger(owner_id,delta,reason,idempotency_key,order_id,research_job_id) values(p_owner_id,p_delta,p_reason,p_idempotency_key,p_order_id,p_job_id) on conflict(idempotency_key) do nothing; if not found then select balance into new_balance from public.credit_wallets where owner_id=p_owner_id; return new_balance; end if; insert into public.credit_wallets(owner_id,balance) values(p_owner_id,greatest(0,p_delta)) on conflict(owner_id) do update set balance=public.credit_wallets.balance+p_delta,updated_at=now() where public.credit_wallets.balance+p_delta>=0 returning balance into new_balance; if new_balance is null then raise exception 'insufficient credits'; end if; return new_balance; end $$;
revoke all on function private.apply_credit_entry(uuid,integer,text,text,uuid,uuid) from public,anon,authenticated;
grant execute on function private.apply_credit_entry(uuid,integer,text,text,uuid,uuid) to service_role;
comment on table public.competitor_listings is 'Only legitimately retrieved public listings. Never seed fictional production research.';
comment on table public.suppliers is 'Listing found, identity verified, and quality audited are deliberately separate states.';
